questionvariables.text:
ta1: 0;
ta2: 90;
/* validate_real: the numerical input accepts i, inf, sets, lists, booleans and equations; only a real number may reach the PRT. Same validator as Ch02_P01_Checks_are_not_a_proof. */
validate_real(ex) := block([sv, fv], sv: ev(ex, simp), fv: errcatch(ev(bfloat(sv), simp)), if ratnump(sv) then "" else if is(fv = []) then "Enter a single real number, for example 3, -1/2 or sqrt(2)." else if bfloatp(first(fv)) then "" else "Enter a single real number, for example 3, -1/2 or sqrt(2).");
validate_deg(ex) := if freeof(%pi, ex) then validate_real(ex) else "Give the angle in degrees: do not use pi.";
/* nearint: a numerical fallback for angles that do not simplify exactly, such as sin(1)^2+cos(1)^2+89 for 90. True when z is a whole number to within rounding error. */
nearint(z) := block([fz], fz: errcatch(ev(float(z), numer, simp)), if is(fz = []) then return(false), fz: first(fz), if floatnump(fz) then (is(abs(fz) < 10^6) and is(abs(fz - round(fz)) < 10^(-12))) else false);

feedbackvariables.text:
t2: ev(ans1, simp);
/* Exact test first; a value that is not rational is then tested numerically. */
holds2: integerp(ev((t2 - 90)/180, simp)) or (not ratnump(t2) and nearint((t2 - 90)/180));
cv2: ev(cos(t2*%pi/180), simp);
showc: freeof(cos, cv2);

t3: ev(ans2, simp);
/* Exact test first; a value that is not rational is then tested numerically. */
holds3: integerp(ev(t3/180, simp)) or (not ratnump(t3) and nearint(t3/180));
sv2: ev(sin(2*t3*%pi/180), simp);
sv1: ev(2*sin(t3*%pi/180), simp);
shows: freeof(sin, sv2) and freeof(sin, sv1);
